#include <algorithm>
#include <iostream>
#include <print>
#include <string>
#include <vector>

class SortedList {
public:
    void insert(int value) {
        items_.insert(std::ranges::upper_bound(items_, value), value);
    }

    bool contains(int value) const {
        return std::ranges::binary_search(items_, value);
    }

    std::size_t size() const {
        return items_.size();
    }

    int min() const {
        return items_.front();
    }

    int max() const {
        return items_.back();
    }

    int median() const {
        return items_[(items_.size() - 1) / 2];
    }

private:
    std::vector<int> items_;
};

int main() {
    SortedList list;
    std::string command;
    while (std::cin >> command) {
        if (command == "add" || command == "has") {
            int x;
            std::cin >> x;
            if (command == "add") {
                list.insert(x);
            } else {
                std::println("{}", list.contains(x) ? "да" : "нет");
            }
        } else if (list.size() == 0) {
            std::println("пусто");
        } else if (command == "min") {
            std::println("{}", list.min());
        } else if (command == "max") {
            std::println("{}", list.max());
        } else {
            std::println("{}", list.median());
        }
    }
    return 0;
}

