#include <format>
#include <iostream>
#include <map>
#include <print>
#include <string>

class Ticket {
public:
    explicit Ticket(char service) : service_(service), number_(++issued_[service]) {}

    std::string code() const {
        return std::format("{}-{:03}", service_, number_);
    }

    static void print_stats() {
        if (issued_.empty()) {
            std::println("пусто");
            return;
        }
        for (const auto &[service, count] : issued_) {
            std::println("{}: {}", service, count);
        }
    }

private:
    inline static std::map<char, int> issued_;
    char service_;
    int number_;
};

int main() {
    std::string command;
    while (std::cin >> command) {
        if (command == "take") {
            char service;
            std::cin >> service;
            Ticket ticket(service);
            std::println("{}", ticket.code());
        } else {
            Ticket::print_stats();
        }
    }
    return 0;
}

